 static GameObject Zone(Effector erosion,Effector blessing,DamageType magic,UnitSelector enemies,UnitSelector friends){string path=V+"CinderMonolith.prefab";var root=new GameObject("CinderMonolith");try{var z=root.AddComponent<GroundDamageZone>();var so=new SerializedObject(z);so.FindProperty("radius").floatValue=3;so.FindProperty("duration").floatValue=7;so.FindProperty("damagePerSecond").floatValue=15;so.FindProperty("damageType").objectReferenceValue=magic;so.FindProperty("zoneEffectors").arraySize=1;so.FindProperty("zoneEffectors").GetArrayElementAtIndex(0).objectReferenceValue=erosion;so.ApplyModifiedPropertiesWithoutUndo();SetSelector(z,"targetSelector",enemies);z.effectorInterval=1;z.allyEffectors=new[]{blessing};z.allySelector=friends;
