 static void RefineCharge(VFXReferencer vfx){var path=AssetDatabase.GetAssetPath(vfx.gameObject);var root=PrefabUtility.LoadPrefabContents(path);try{var first=root.transform.GetChild(0);first.localScale=Vector3.one*.55f;AddGroundLines(root,1.2f,-.9f,false);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
 static void AddGroundLines(GameObject root,float radius,float y,bool cracks){var mat=AssetDatabase.LoadAssetAtPath<Material>(V+"CinderBoundary.mat");if(!mat){mat=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/VFX/Materials/LaserBeam.mat"));AssetDatabase.CreateAsset(mat,V+"CinderBoundary.mat");}var child=root.transform.Find("CinderBoundary");if(!child){child=new GameObject("CinderBoundary").transform;child.SetParent(root.transform,false);}var line=child.GetComponent<LineRenderer>();if(!line)line=child.gameObject.AddComponent<LineRenderer>();line.sharedMaterial=mat;line.useWorldSpace=false;line.loop=true;line.widthMultiplier=.035f;line.startColor=line.endColor=new Color(.16f,.55f,.025f,.6f);line.positionCount=64;for(int i=0;i<64;i++){float a=i*Mathf.PI*2/64;line.SetPosition(i,new Vector3(Mathf.Cos(a)*radius,y,Mathf.Sin(a)*radius));}
 if(cracks)for(int n=0;n<7;n++){var go=new GameObject("FelCrack"+n);go.transform.SetParent(root.transform,false);var lr=go.AddComponent<LineRenderer>();lr.sharedMaterial=mat;lr.useWorldSpace=false;lr.widthMultiplier=.045f;lr.startColor=lr.endColor=new Color(.1f,.45f,.015f,.45f);lr.positionCount=5;for(int j=0;j<5;j++){float a=n*Mathf.PI*2/7+(j%2==0?.07f:-.07f);float r=.35f+j*.58f;lr.SetPosition(j,new Vector3(Mathf.Cos(a)*r,.09f,Mathf.Sin(a)*r));}}
 }
