 static void Assign(Ability[] abilities){const string path="Assets/Resources/UnitPrefabs/Units/Heroes/Orcs/Gurtag.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var u=root.GetComponent<Unit>();u.abilities=abilities;u.abilityLevel=new int[abilities.Length];var animator=root.GetComponentInChildren<Animator>(true);string cp=A+"Gurtag_Skills.controller";var ctrl=AssetDatabase.LoadAssetAtPath<AnimatorController>(cp);if(!ctrl){AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(animator.runtimeAnimatorController),cp);ctrl=AssetDatabase.LoadAssetAtPath<AnimatorController>(cp);}var sm=ctrl.layers[0].stateMachine;var cast=sm.states.Select(x=>x.state).FirstOrDefault(x=>x.name=="cast");if(!cast)cast=sm.AddState("cast");var attack=sm.states.Select(x=>x.state).First(x=>x.name=="attack0");string clipPath=A+"Gurtag_Cast.anim";var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(clipPath);if(!clip){clip=UnityEngine.Object.Instantiate((AnimationClip)attack.motion);AssetDatabase.CreateAsset(clip,clipPath);}AnimationUtility.SetAnimationEvents(clip,Array.Empty<AnimationEvent>());var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=false;AnimationUtility.SetAnimationClipSettings(clip,settings);cast.motion=clip;cast.speed=clip.length/.9f;if(cast.transitions.Length==0){var tr=cast.AddTransition(sm.states.Select(x=>x.state).First(x=>x.name=="idleReady"));tr.hasExitTime=true;tr.exitTime=1;tr.duration=.08f;}var brace=sm.states.Select(x=>x.state).FirstOrDefault(x=>x.name=="brace");if(!brace)brace=sm.AddState("brace");brace.motion=sm.states.Select(x=>x.state).First(x=>x.name=="idleReady").motion;brace.speed=0;animator.runtimeAnimatorController=ctrl;EditorUtility.SetDirty(ctrl);EditorUtility.SetDirty(clip);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
